package pe.animetv;
import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.RobolectricTestRunner;import org.robolectric.annotation.Config;import okhttp3.*;import okhttp3.mockwebserver.*;import java.util.*;import java.util.concurrent.atomic.AtomicLong;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class JkCdnInterceptorTest {
 private MockWebServer origin,mirror;private byte[] payload;private AtomicLong clock;private JkCdnInterceptor policy;private OkHttpClient client;
 @Before public void start()throws Exception{origin=new MockWebServer();mirror=new MockWebServer();origin.start();mirror.start();payload=new byte[100000];new Random(20).nextBytes(payload);clock=new AtomicLong();policy=new JkCdnInterceptor(r->r.url().encodedPath().endsWith(".ts"),u->mirror.url(u.encodedPath()),clock::get);client=new OkHttpClient.Builder().addInterceptor(policy).build();}
 @After public void stop()throws Exception{origin.shutdown();mirror.shutdown();client.dispatcher().executorService().shutdownNow();client.connectionPool().evictAll();}
 private MockResponse video(byte[] data){return new MockResponse().setHeader("Content-Type","video/mp2t").setBody(new okio.Buffer().write(data));}
 @Test public void verifiedReplicaPreservesEveryByte()throws Exception{origin.enqueue(video(payload));mirror.enqueue(video(payload));policy.markSlow(origin.url("/").host());try(Response r=client.newCall(new Request.Builder().url(origin.url("/video.ts")).build()).execute()){assertArrayEquals(payload,r.body().bytes());assertEquals(mirror.getPort(),r.request().url().port());}assertEquals(1,origin.getRequestCount());assertEquals(1,mirror.getRequestCount());}
 @Test public void differentReplicaFallsBackToOriginal()throws Exception{byte[] other=payload.clone();other[100]^=1;origin.enqueue(video(payload));origin.enqueue(video(payload));mirror.enqueue(video(other));policy.markSlow(origin.url("/").host());try(Response r=client.newCall(new Request.Builder().url(origin.url("/video.ts")).build()).execute()){assertArrayEquals(payload,r.body().bytes());assertEquals(origin.getPort(),r.request().url().port());}assertEquals(2,origin.getRequestCount());}
 @Test public void rangeMismatchNeverReplacesOriginal()throws Exception{origin.enqueue(video(payload));origin.enqueue(video(payload));mirror.enqueue(video(payload).setResponseCode(206).setHeader("Content-Range","bytes 0-99999/100000"));policy.markSlow(origin.url("/").host());try(Response r=client.newCall(new Request.Builder().url(origin.url("/video.ts")).build()).execute()){assertEquals(origin.getPort(),r.request().url().port());assertArrayEquals(payload,r.body().bytes());}}
 @Test public void expiredQuarantineUsesOriginalWithoutProbe()throws Exception{policy.markSlow(origin.url("/").host());clock.set(120001);origin.enqueue(video(payload));try(Response r=client.newCall(new Request.Builder().url(origin.url("/video.ts")).build()).execute()){assertArrayEquals(payload,r.body().bytes());}assertEquals(0,mirror.getRequestCount());}
 @Test public void slowBodyStopsAndNextAttemptUsesVerifiedMirror()throws Exception{origin.enqueue(video(payload));Response r=client.newCall(new Request.Builder().url(origin.url("/video.ts")).build()).execute();clock.set(7000);try{r.body().bytes();fail();}catch(java.io.IOException expected){assertTrue(expected.getMessage().contains("nodo CDN lento"));}finally{r.close();}origin.enqueue(video(payload));mirror.enqueue(video(payload));try(Response next=client.newCall(new Request.Builder().url(origin.url("/video.ts")).build()).execute()){assertArrayEquals(payload,next.body().bytes());assertEquals(mirror.getPort(),next.request().url().port());}}
 @Test public void policyIsConfinedToPublishedJkTsHosts(){String ref="https://jkanime.net/jkplayer/um";assertTrue(JkCdnInterceptor.eligible(new Request.Builder().url("https://cdn4.ducvomes.com/ja/segs/a/video.ts").header("Referer",ref).build()));for(String url:List.of("https://cdn4.ducvomes.com.attacker.test/ja/segs/a/video.ts","http://cdn4.ducvomes.com/ja/segs/a/video.ts","https://cdn4.ducvomes.com/else/video.ts"))assertFalse(JkCdnInterceptor.eligible(new Request.Builder().url(url).header("Referer",ref).build()));assertFalse(JkCdnInterceptor.eligible(new Request.Builder().url("https://cdn4.ducvomes.com/ja/segs/a/video.ts").header("Referer","https://other.test/").build()));assertTrue(JkCdnInterceptor.ownHls("Magi","application/x-mpegURL"));assertFalse(JkCdnInterceptor.ownHls("Voe","application/x-mpegURL"));}
}
